#pragma once
#include "../../support.hpp"
#include "../../data-structures/heaps/binary-heap.hpp"
namespace algs {
template<class N>struct AStarNeighbor{N node;double cost;};template<class N>struct AStarOptions{N start,goal;std::function<std::vector<AStarNeighbor<N>>(const N&)>neighbors;std::function<double(const N&)>heuristic;std::function<std::string(const N&)>key=[](const N&n){return text(n);};};template<class N>struct AStarResult{std::vector<N>path;double cost;};template<class N>std::optional<AStarResult<N>>aStar(const AStarOptions<N>&o){struct Entry{N node;double cost,estimate;};std::string goal=o.key(o.goal);std::map<std::string,double>best{{o.key(o.start),0}};std::map<std::string,N>came;BinaryHeap<Entry>open([](const Entry&a,const Entry&b){return defaultCompare(a.estimate,b.estimate);});open.push({o.start,0,o.heuristic(o.start)});while(!open.isEmpty()){auto e=*open.pop();auto k=o.key(e.node);if(e.cost>best[k])continue;if(k==goal){std::vector<N>path{e.node};auto it=came.find(k);while(it!=came.end()){path.push_back(it->second);it=came.find(o.key(it->second));}std::reverse(path.begin(),path.end());return AStarResult<N>{path,e.cost};}for(auto next:o.neighbors(e.node)){auto nk=o.key(next.node);double cost=e.cost+next.cost;auto it=best.find(nk);if(it==best.end()||cost<it->second){best[nk]=cost;came.insert_or_assign(nk,e.node);open.push({next.node,cost,cost+o.heuristic(next.node)});}}}return {};}
using Cell=std::pair<int,int>;inline std::optional<std::vector<Cell>>aStarGrid(const std::vector<std::string>&g,Cell start,Cell goal,char wall='#'){AStarOptions<Cell>o{start,goal,[&](const Cell&v){std::vector<AStarNeighbor<Cell>>ns;for(auto [dr,dc]:std::vector<Cell>{{1,0},{-1,0},{0,1},{0,-1}}){int r=v.first+dr,c=v.second+dc;if(r>=0&&r<int(g.size())&&c>=0&&c<int(g[r].size())&&g[r][c]!=wall)ns.push_back({{r,c},1});}return ns;},[goal](const Cell&v){return double(std::abs(v.first-goal.first)+std::abs(v.second-goal.second));},[](const Cell&v){return std::to_string(v.first)+","+std::to_string(v.second);}};auto r=aStar(o);return r?std::optional<std::vector<Cell>>(r->path):std::optional<std::vector<Cell>>{};}
}
